-- GENERATED by `wfj generate` from data/gossip/gossip-d9.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["d9030dc893b17fb8"] = { "Non ho altro sapere da trasmetterti. Passa sotto l'arco e scendi la rampa verso sud-est, poi parla con il dottor Herbert Halsey. È un Reietto che può insegnarti tecniche più avanzate.", "." },
  ["d90de0ae005f10e0"] = { "Prima di morire lavoravo in una biblioteca; non avevo niente a che fare con guerre e pestilenze. Non ho mai chiesto di diventare così. D'altra parte, ora che la mia mente è di nuovo mia, non ho intenzione di arrendermi senza combattere.", "." },
  ["d9105a64e75cf79e"] = { "Ora, dove ho messo le formule della ⟦Venture Company=S.P.R. & Co.⟧?", "." },
  ["d910ab55575d08d4"] = { "Fatevi avanti, Sognatori, e reclamate la vostra vendetta!", "." },
  ["d91ad167ea7af0ef"] = { "Vai a Orgrimmar, {name}. Saluta Thrall da parte mia!", "." },
  ["d91d539d5f66491d"] = { "Finalmente... fuori dalla sua presa maledetta!", "." },
  ["d924a1397fa96a9a"] = { "Salute, {name}. Sono il dottor Gregory Victor, primario di traumatologia del Centro Traumi dell'⟦Horde=Orda⟧.", "." },
  ["d93368049a05069d"] = { "Chiunque sia sospetto va abbattuto subito. Tutti ai vostri posti il prima possibile!", "." },
  ["d9355a6b551b77bc"] = { "Qui per l'addestramento, eh? Ho appena cominciato l'addestramento anch'io, ma ti insegnerò volentieri quel che posso.", "." },
  ["d938cb9642c19cf9"] = { "Sì, ti prego, richiamalo!", "." },
  ["d93c9d019f8929da"] = { "Sei qui per la verga? O magari vuoi solo fare scorta di rune?\n\nUn momento! Non è che stai solo cercando di rifilarmi un mucchio di cianfrusaglie?! Maledetta la mia smania infinita di comprare, comprare, comprare!", "." },
  ["d96274e147f4a53f"] = { "Insieme, le due parti torneranno a essere una cosa sola.", "." },
  ["d964552e98b05743"] = { "È giunto il momento che l'⟦Horde=Orda⟧ e l'⟦Alliance=Alleanza⟧ guardino a nord e all'invasione del Flagello. Negli ultimi giorni, territori di tutto Kalimdor e dei Regni Orientali sono stati attaccati. Prenderai le armi per salvare la tua terra dalla distruzione per mano loro?", "." },
  ["d9646336d8c3ebb9"] = { "Questa è un'attrezzatura specializzata! Non maneggiarla con leggerezza, e naturalmente non provare a farla funzionare se hai bevuto troppo di quel rum volatile che, a quanto sento, ti piace tanto...\n\nA proposito... non è che per caso ne hai un po', di quella roba schifosa?", "." },
  ["d96a8830a71d7a6f"] = { "Ti do il benvenuto a Thelsamar, una seconda casa a Loch Modan!\n\nThelsamar è un bel posto, ma per chi risponde alla chiamata del dovere non è tutto birra e carne salata! Se te la senti di affrontare il pericolo in nome dell'⟦Alliance=Alleanza⟧, leggi l'avviso fuori dalla sede di Thelsamar della ⟦Explorers' League=Lega degli Esploratori⟧.", "." },
  ["d96d5fbb7c46420a"] = { "Il Flagello ha schierato solo piccole forze contro ciascuna delle capitali di Azeroth, mentre il grosso delle sue truppe attacca periodicamente le seguenti terre:\n\nAzshara, le ⟦Blasted Lands=Terre Devastate⟧, le ⟦Burning Steppes=Steppe Ardenti⟧, il Deserto di Tanaris, le ⟦Eastern Plaguelands=Terre Infette Orientali⟧ e ⟦Winterspring=Fontefredda⟧.", "." },
  ["d96ef658fd86937e"] = { "La mascherata è finita, lady Prestor. O dovrei chiamarti con il tuo vero nome... Onyxia...", "." },
  ["d970a2277ff57082"] = { "Kibler è sotto indagine da parte della G.E.T.A.", "." },
  ["d977b9599217d5f0"] = { "Che fortuna. Di solito devo lasciare la mia tana per nutrirmi.", "." },
  ["d980642e88d6dc93"] = { "Comincia a fare freschino qui fuori. Credo che andrò a scaldarmi accanto al fuoco e a farmi una pinta, o dodici.", "." },
  ["d9810225cb2edcef"] = { "Se non fosse per quella maledetta fortuna gnomesca, non vincerebbero mai una corsa!", "." },
  ["d990bb297ab8278d"] = { "Litigare di continuo non ci porterà da nessuna parte. Dobbiamo agire.", "." },
  ["d9948d48a39c598b"] = { "Ben fatto! La tua conoscenza delle pozioni sta progredendo bene.", "." },
  ["d99635213fcb0428"] = { "Continua, ti prego, questa storia è intrigante.", "." },
  ["d9986a819b17d81f"] = { "Attendi mentre cerco di unire i frammenti perché tornino interi.", "." },
  ["d99c53ee1040cabf"] = { "Ti interessa il cuoio, eh? Mi sa che dovresti parlare con Simon Tanner, a Old Town. Ha una bottega che si chiama Protective Hide.", "." },
  ["d99f5863bdcc4743"] = { "Va bene, va bene! Basta combattere. Nessun altro deve farsi male.", "." },
  ["d9a26a8ee673fc22"] = { "No! Non puoi essere più forte del Foulweald! No!!", "." },
  ["d9a32818da7e9ac9"] = { "La Torre di Brinarossa protegge il ⟦Iceblood Garrison=Presidio di Brinarossa⟧ da sud-est.\n\nÈ controllata dall'⟦Horde=Orda⟧.", "." },
  ["d9ace3e2259f8fd2"] = { "Nella tua corsa verso la gloria, hai dato per scontato che il ritmo del gioco ruotasse attorno alle tue azioni. Riesci anche solo a immaginare quanto suoni assurdo per un essere come me? Un essere che, volendo, potrebbe far sì che i tuoi stessi pensieri insignificanti schiaccino quella massa grigia grande quanto una nocciolina che ti galleggia nel cranio.", "." },
  ["d9b540bba6767a43"] = { "È l'ora dell'evento principale! Skarr the Unbreakable è nella Fossa Infausta!", "." },
  ["d9ba7008f391e1e4"] = { "Solo guai da queste parti. Ho provato a dire a quello sciocco di Saldean di andarsene finché poteva, ma non vuole sentire ragioni. Io però la testa ce l'ho. Io e Verna ce ne andiamo appena sistemiamo questo carro.", "." },
  ["d9bbc9bd0a8d70e2"] = { "Mai avrei pensato di trovare qualcosa in condizioni così perfette.", "." },
  ["d9c1463d28357592"] = { "Altri agenti della ⟦Syndicate=Lega dei Tagliagole⟧, scommetto! Non vi riprenderete mai Alterac... né ⟦Southshore=Riva del Sud⟧!", "." },
  ["d9c3d93cb9496751"] = { "La Banca di ⟦Thunder Bluff=Picco del Tuono⟧ si trova sull'altura inferiore.", "." },
  ["d9c58336a4e23ece"] = { "Vieni per la birra, resta per l'atmosfera!", "." },
  ["d9c80f835ecd2109"] = { "Se resti qui a riposare ancora qualche istante, otterrai un beneficio dal riposo vicino alla tenda che ho montato alle mie spalle.", "." },
  ["d9d137f07bea6027"] = { "Un orco, un vero guerriero orco, desidera una cosa sola: morire nella gloria della battaglia contro un nemico odiato.", "." },
  ["d9d1441aab22e71d"] = { "{name}, le mie ferite sono gravi. Perdona la mia lentezza, ma le ferite non mi permettono di camminare più in fretta.", "." },
  ["d9d1c177441e32ac"] = { "Ah, non c'è niente di meglio di un sacerdote per curare i tuoi mali. Certo, anche una bella pinta alta cura un sacco di mali, ma non credo che Braenna Flintcrag insegni a fare la birra. Immagino che dovrai accontentarti di un po' di addestramento da sacerdote nella Hall of Mysteries.", "." },
  ["d9dbc126354c5ac8"] = { "Cadi!", "." },
  ["d9e0c375d64185c9"] = { "Ci condanneresti tutti...", "." },
  ["d9e374f31ce5b711"] = { "<Signore/Signora>, sì, <signore/signora>! Il soldato semplice Porter a rapporto, a tua disposizione per raccogliere il cuoio medio che ti serve. La Guerra di ⟦Ahn'Qiraj=Ahn'qiraj⟧ si avvicina e dobbiamo essere preparati il più possibile.\n\nCome vedi, abbiamo raccolto esattamente $2063w pezzi di cuoio medio, e mi hanno incaricato di raccoglierne in totale $2064w.", "." },
  ["d9e3998cfab17c60"] = { "L'Incubo è finalmente finito! ⟦Darrowshire=Borgo di Darrow⟧, perdonami!", "." },
  ["d9f19cff7c5db817"] = { "Ora è il momento di porre fine al suo regno, Marcus. Fatti da parte, amico.", "." },
  ["d9f75dadc6e76f0a"] = { "Ahh... <benvenuto/benvenuta> nel mio salotto.", "." },
  ["d9fd2e5f8f1c94b2"] = { "Ti presento il ⟦Libram of Constitution=Compendio sulla Costituzione⟧.", "." },
})
